{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const table = () => ({ t: 'table', map: new Map(), defined: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  fail(m) {
    throw new Error(m)
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  // at end of line or at a comment
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  quoted() {
    const q = this.s[this.i]
    this.i++
    let out = ''
    if (q === "'") {
      const j = this.s.indexOf("'", this.i)
      if (j < 0) this.fail('unterminated string')
      out = this.s.slice(this.i, j)
      this.i = j + 1
      return out
    }
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) this.fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) this.fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) {
          out += map[e]
          this.i += 2
        } else if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else {
          const cp = String.fromCodePoint(this.s.codePointAt(this.i + 1))
          this.fail('invalid escape \\' + cp)
        }
      } else {
        out += c
        this.i++
      }
    }
  }
  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (st === this.i) this.fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }
  value(prefix) {
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') this.fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.s[this.i] !== undefined && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    this.fail('invalid value ' + w)
  }
  array(prefix) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.value(prefix))
      this.ws()
      if (this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (this.s[this.i] === ']') continue
      this.fail('unterminated array')
    }
  }
  inline(prefix) {
    this.i++
    const t = table()
    t.defined = true
    this.ws()
    if (this.s[this.i] === '}') {
      this.i++
      return t
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value(prefix)
      assign(t, names, v, prefix)
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (this.s[this.i] === ',') {
        this.i++
        continue
      }
      if (this.s[this.i] === '}') {
        this.i++
        return t
      }
      this.fail('unterminated inline table')
    }
  }
}

const join = (p, n) => (p ? p + '.' + n : n)

// Walk through names (all but the last), creating tables.
function walk(cur, names, prefix, upto) {
  let path = prefix
  for (let k = 0; k < upto; k++) {
    const n = names[k]
    path = join(path, n)
    let nx = cur.map.get(n)
    if (!nx) {
      nx = table()
      cur.map.set(n, nx)
    }
    if (nx.t === 'array' && nx.aot) nx = nx.items[nx.items.length - 1]
    if (nx.t !== 'table') throw new Error(path + ' is not a table')
    cur = nx
  }
  return { cur, path }
}

function assign(cur, names, value, prefix) {
  const r = walk(cur, names, prefix, names.length - 1)
  const last = names[names.length - 1]
  if (r.cur.map.has(last)) throw new Error(`key ${join(r.path, last)} is defined twice`)
  r.cur.map.set(last, value)
}

export function parse(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = table()
  root.defined = true
  let current = root
  let lineNo = 0
  try {
    for (const line of lines) {
      lineNo++
      const p = new LineParser(line)
      p.ws()
      const c = line[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        current = header(p, root)
        continue
      }
      const names = p.dotted()
      p.ws()
      if (p.s[p.i] !== '=') throw new Error('expected key = value')
      p.i++
      p.ws()
      const v = p.value(names.join('.'))
      p.ws()
      if (!p.atEnd()) throw new Error('trailing text after a value')
      assign(current, names, v, currentPrefix.get(current) || '')
    }
  } catch (e) {
    if (e instanceof ParseError) throw e
    throw new ParseError(e.message, lineNo)
  }
  return root
}

const currentPrefix = new WeakMap()

function header(p, root) {
  p.i++
  const aot = p.s[p.i] === '['
  if (aot) p.i++
  p.ws()
  const names = p.dotted()
  p.ws()
  const closeFail = () => {
    throw new Error('unterminated table header')
  }
  if (p.s[p.i] !== ']') closeFail()
  p.i++
  if (aot) {
    if (p.s[p.i] !== ']') closeFail()
    p.i++
  }
  p.ws()
  if (!p.atEnd()) throw new Error('trailing text after a table header')

  const full = names.join('.')
  const r = walk(root, names, '', names.length - 1)
  const last = names[names.length - 1]
  const ex = r.cur.map.get(last)
  let result
  if (aot) {
    if (!ex) {
      const a = { t: 'array', items: [], aot: true }
      r.cur.map.set(last, a)
      result = table()
      a.items.push(result)
    } else if (ex.t === 'array' && ex.aot) {
      result = table()
      ex.items.push(result)
    } else throw new Error(full + ' is not an array of tables')
  } else {
    if (!ex) {
      result = table()
      r.cur.map.set(last, result)
    } else if (ex.t === 'table') {
      if (ex.defined) throw new Error(`table ${full} is defined twice`)
      result = ex
    } else throw new Error(full + ' is not a table')
    result.defined = true
  }
  currentPrefix.set(result, full)
  return result
}
"}

